package cn.lili.modules.community.p0.presentation;

import cn.lili.common.security.session.SessionDomain;
import cn.lili.modules.community.p0.support.*;
import cn.lili.modules.community.p0.admission.AdmissionService;
import cn.lili.modules.community.p0.catalog.GoodsManagementService;
import cn.lili.modules.community.p0.agreement.AgreementService;
import cn.lili.modules.community.p0.fulfillment.FulfillmentService;
import com.google.gson.*;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.util.*;
import static cn.lili.modules.community.p0.support.Stage1Json.*;
import static cn.lili.modules.community.p0.presentation.ManagerPresentationViews.*;

@Service
@ConditionalOnProperty(name="p0.stage1.enabled",havingValue="true")
@org.springframework.context.annotation.Conditional(ManagerPresentationCondition.class)
@Transactional(readOnly=true)
public class ManagerPresentationService {
    private final Stage1Db db;private final Stage1Context context;private final ManagerLookupService lookup;private final AdmissionService admission;private final GoodsManagementService goods;private final FulfillmentService fulfillment;
    public ManagerPresentationService(Stage1Db db,Stage1Context context,ManagerLookupService lookup,AdmissionService admission,GoodsManagementService goods,FulfillmentService fulfillment){this.db=db;this.context=context;this.lookup=lookup;this.admission=admission;this.goods=goods;this.fulfillment=fulfillment;}
    public Object applications(String kind,String status,String query,int page,int size){lookup.require("admission.review");AgreementService.page(page,size);if(kind!=null)Stage1Exception.require(Set.of("ADMISSION","PROFILE_CHANGE","QUALIFICATION_CHANGE").contains(kind),422,"APPLICATION_KIND_INVALID");if(status!=null)Stage1Exception.require(Set.of("DRAFT","SUBMITTED","APPROVED","REJECTED").contains(status),422,"APPLICATION_STATUS_INVALID");String q=search(query);List<Object> args=new ArrayList<>();String from=" FROM li_p0_application a LEFT JOIN li_store s ON s.id=a.store_id LEFT JOIN li_store_detail d ON d.store_id=a.store_id LEFT JOIN li_p0_application_revision r ON r.application_id=a.id AND r.revision=a.revision WHERE 1=1";if(kind!=null){from+=" AND a.kind=?";args.add(kind);}if(status!=null){from+=" AND a.status=?";args.add(status);}if(q!=null){from+=" AND (COALESCE(JSON_UNQUOTE(JSON_EXTRACT(a.draft_payload,'$.storeName')),s.store_name) LIKE ? ESCAPE '!' OR COALESCE(JSON_UNQUOTE(JSON_EXTRACT(a.draft_payload,'$.legalName')),d.company_name) LIKE ? ESCAPE '!')";args.add(like(q));args.add(like(q));}long count=db.count("SELECT COUNT(*)"+from,args.toArray());args.add(size);args.add((page-1)*size);var rows=db.rows("SELECT CAST(a.id AS CHAR) AS id,CAST(a.store_id AS CHAR) AS storeId,a.kind,a.status,a.revision,a.version,COALESCE(JSON_UNQUOTE(JSON_EXTRACT(a.draft_payload,'$.storeName')),s.store_name) AS storeName,COALESCE(JSON_UNQUOTE(JSON_EXTRACT(a.draft_payload,'$.legalName')),d.company_name) AS legalName,a.updated_at,r.created_at AS submitted_at"+from+" ORDER BY a.updated_at DESC,a.id DESC LIMIT ? OFFSET ?",args.toArray());return ManagerPresentationViews.page(count,page,size,rows.stream().map(r->map("id",id(r,"id"),"storeId",id(r,"storeId"),"kind",r.get("kind"),"status",r.get("status"),"revision",r.get("revision"),"version",r.get("version"),"storeName",r.get("storeName"),"legalName",r.get("legalName"),"updatedAt",instant(r.get("updated_at")),"submittedAt",instant(r.get("submitted_at")))).toList());}
    public Object application(String id,Integer revision){lookup.require("admission.review");identifier(id);var current=db.required("SELECT * FROM li_p0_application WHERE id=?",id);if(revision!=null)Stage1Exception.require(revision>=1,422,"REVISION_INVALID");var snapshot=revision!=null?db.required("SELECT * FROM li_p0_application_revision WHERE application_id=? AND revision=?",id,revision):"SUBMITTED".equals(id(current,"status"))?db.required("SELECT * FROM li_p0_application_revision WHERE application_id=? AND revision=?",id,current.get("revision")):null;
        var payload=object(snapshot==null?current.get("draft_payload"):snapshot.get("payload"));var history=db.rows("SELECT r.*,u.nick_name AS operator_name FROM li_p0_application_revision r LEFT JOIN li_admin_user u ON u.id=r.reviewer_id WHERE r.application_id=? ORDER BY r.revision DESC",id).stream().map(r->map("revision",r.get("revision"),"status",r.get("status"),"reason",r.get("reason"),"reviewerName",operator(map("operator_name",r.get("operator_name"),"actor_id",r.get("reviewer_id"))),"submittedAt",instant(r.get("created_at")),"reviewedAt",instant(r.get("reviewed_at")))).toList();
        JsonObject effective=null;if(!"ADMISSION".equals(id(current,"kind"))&&current.get("store_id")!=null)effective=ManagerPresentationViews.profile(admission.profile(id(current,"store_id")));
        return map("id",id,"storeId",id(current,"store_id"),"kind",current.get("kind"),"status",snapshot==null?current.get("status"):snapshot.get("status"),"currentStatus",current.get("status"),"revision",revision==null?current.get("revision"):revision,"currentRevision",current.get("revision"),"version",current.get("version"),"historical",revision!=null,"payload",payload,"currentEffective",effective,"baseStoreVersion",current.get("base_store_version"),"history",history,"updatedAt",instant(current.get("updated_at")),"submittedAt",snapshot==null?null:instant(snapshot.get("created_at")));
    }
    public Object stores(String q,String state,int page,int size){lookup.require("store.read");AgreementService.page(page,size);q=search(q);if(state!=null)Stage1Exception.require(Set.of("OPEN","CLOSED").contains(state),422,"STORE_STATE_INVALID");List<Object> args=new ArrayList<>();String from=" FROM li_store s JOIN li_p0_store_control c ON c.store_id=s.id JOIN li_store_detail d ON d.store_id=s.id LEFT JOIN li_member m ON m.id=s.member_id WHERE c.admission_state='APPROVED' AND s.delete_flag=0";if(q!=null){from+=" AND (s.store_name LIKE ? ESCAPE '!' OR d.company_name LIKE ? ESCAPE '!')";args.add(like(q));args.add(like(q));}if(state!=null){from+=" AND s.store_disable=?";args.add(state);}long count=db.count("SELECT COUNT(*)"+from,args.toArray());args.add(size);args.add((page-1)*size);return ManagerPresentationViews.page(count,page,size,db.rows("SELECT CAST(s.id AS CHAR) AS id,s.store_name AS storeName,d.company_name AS legalName,m.nick_name AS ownerName,s.store_disable AS state,c.version"+from+" ORDER BY s.update_time DESC,s.id DESC LIMIT ? OFFSET ?",args.toArray()));}
    public Object store(String id){lookup.require("store.read");identifier(id);var result=ManagerPresentationViews.profile(admission.profile(id));var owner=db.one("SELECT m.nick_name FROM li_store s JOIN li_member m ON m.id=s.member_id WHERE s.id=? AND s.delete_flag=0",id);result.addProperty("ownerName",owner==null?null:id(owner,"nick_name"));result.add("categoryNames",object(map("values",categoryNames(result.getAsJsonArray("categoryIds")))) .get("values"));return result;}
    private Object categoryNames(JsonArray ids){var rows=lookup.categoryRows();var result=new ArrayList<Object>();if(ids!=null)for(var id:ids)result.add(map("id",id.getAsString(),"path",lookup.categoryPath(id.getAsString(),rows)));return result;}
    public Object staff(String store,int page,int size){lookup.require("store.read");identifier(store);AgreementService.page(page,size);db.required("SELECT store_id FROM li_p0_store_control WHERE store_id=? AND admission_state='APPROVED'",store);String from=" FROM li_clerk c JOIN li_member m ON m.id=c.member_id JOIN li_p0_clerk_control k ON k.clerk_id=c.id WHERE c.store_id=? AND c.delete_flag=0";var rows=db.rows("SELECT c.id,c.status,c.shopkeeper,m.nick_name,k.version,k.revoked"+from+" ORDER BY c.create_time DESC,c.id DESC LIMIT ? OFFSET ?",store,size,(page-1)*size);return ManagerPresentationViews.page(db.count("SELECT COUNT(*)"+from,store),page,size,rows.stream().map(r->map("id",id(r,"id"),"displayName",r.get("nick_name"),"owner",flag(r,"shopkeeper"),"state",flag(r,"revoked")?"REVOKED":flag(r,"status")?"ACTIVE":"DISABLED","version",r.get("version"),"roleNames",db.rows("SELECT r.name FROM li_clerk_role cr JOIN li_store_role r ON r.id=cr.role_id WHERE cr.clerk_id=? AND r.delete_flag=0 ORDER BY r.id",r.get("id")).stream().map(v->v.get("name")).toList())).toList());}
    public Object history(String store,int page,int size){lookup.require("store.read");identifier(store);AgreementService.page(page,size);db.required("SELECT store_id FROM li_p0_store_control WHERE store_id=? AND admission_state='APPROVED'",store);String from=" FROM li_p0_audit a LEFT JOIN li_admin_user u ON u.id=a.actor_id AND a.identity_domain='MANAGER' WHERE a.store_id=? AND a.action IN ('application.submit','application.approve','application.reject','profile.update','profile-change.submit','qualification.submit','store.close','store.reopen','qualification.revoke')";return ManagerPresentationViews.page(db.count("SELECT COUNT(*)"+from,store),page,size,db.rows("SELECT a.*,u.nick_name AS operator_name"+from+" ORDER BY a.created_at DESC,a.id DESC LIMIT ? OFFSET ?",store,size,(page-1)*size).stream().map(r->map("id",id(r,"id"),"objectId",id(r,"object_id"),"action",r.get("action"),"beforeVersion",r.get("before_version"),"afterVersion",r.get("after_version"),"reason",r.get("reason"),"operatorName","MANAGER".equals(r.get("identity_domain"))?operator(r):"本店授权人员","at",instant(r.get("created_at")))).toList());}
    public Object objectHistory(String store,String type,String objectId,int page,int size){
        if(type==null){Stage1Exception.require(objectId==null,422,"HISTORY_SCOPE_INVALID");return history(store,page,size);}
        Stage1Exception.require(Set.of("AGREEMENT","RULE").contains(type),422,"HISTORY_SCOPE_INVALID");lookup.require("store.read");lookup.require(type.equals("AGREEMENT")?"agreement.read":"rule.read");identifier(store);identifier(objectId);AgreementService.page(page,size);
        String table=type.equals("AGREEMENT")?"li_p0_agreement":"li_p0_commission_rule",prefix=type.equals("AGREEMENT")?"agreement.%":"rule.%";db.required("SELECT id FROM "+table+" WHERE id=? AND store_id=?",objectId,store);
        String from=" FROM li_p0_audit a LEFT JOIN li_admin_user u ON u.id=a.actor_id AND a.identity_domain='MANAGER' WHERE a.store_id=? AND a.object_id=? AND a.action LIKE ?";
        var rows=db.rows("SELECT a.*,u.nick_name AS operator_name"+from+" ORDER BY a.created_at DESC,a.id DESC LIMIT ? OFFSET ?",store,objectId,prefix,size,(page-1)*size).stream().map(r->map("id",id(r,"id"),"action",r.get("action"),"beforeVersion",r.get("before_version"),"afterVersion",r.get("after_version"),"reason",r.get("reason"),"operatorName",operator(r),"at",instant(r.get("created_at")))).toList();
        return map("objectType",type,"objectId",objectId,"total",db.count("SELECT COUNT(*)"+from,store,objectId,prefix),"pageNumber",page,"pageSize",size,"records",rows);
    }
    public Object goods(String store,String status,String q,Boolean forced,String market,String stock,String category,boolean review,int page,int size){lookup.require(review?"goods.review":"goods.read");AgreementService.page(page,size);if(store!=null)identifier(store);if(category!=null)identifier(category);q=search(q);status=review?"SUBMITTED":status;
        var base=category==null?object(goods.list(store,status,q,forced,market,stock,page,size)):categoryPage(store,status,q,forced,market,stock,category,page,size);
        var rows=base.getAsJsonArray("records");enrich(rows);base.addProperty("pageNumber",page);base.addProperty("pageSize",size);return base;
    }
    private JsonObject categoryPage(String store,String status,String q,Boolean forced,String market,String stock,String category,int page,int size){
        // Original service owns all validation and item projections. Only candidate selection/counting is extended here.
        goods.list(store,status,q,forced,market,stock,1,1);
        var categories=lookup.categoryIds(category);Stage1Exception.require(!categories.isEmpty(),422,"ID_REQUIRED");var args=new ArrayList<Object>();
        String from=" FROM li_p0_goods_control c JOIN li_p0_goods_draft d ON d.goods_id=c.goods_id LEFT JOIN li_goods g ON g.id=c.goods_id WHERE c.category_id IN ("+String.join(",",Collections.nCopies(categories.size(),"?"))+")";args.addAll(categories);
        if(store!=null){from+=" AND c.store_id=?";args.add(store);}if(status!=null){from+=" AND c.review_status=?";args.add(status);}if(forced!=null){from+=" AND c.forced_off=?";args.add(forced);}if(market!=null){from+=" AND COALESCE(g.market_enable,'DOWN')=?";args.add(market);}if(q!=null){from+=" AND JSON_UNQUOTE(JSON_EXTRACT(d.payload,'$.name')) LIKE ? ESCAPE '!'";args.add(like(q));}
        if(stock!=null){String sku=" FROM li_goods_sku s JOIN li_p0_sku_control sc ON sc.sku_id=s.id WHERE sc.goods_id=c.goods_id AND sc.enabled=1 AND s.delete_flag=0",has="EXISTS(SELECT 1"+sku+")",available="EXISTS(SELECT 1"+sku+" AND s.quantity>0)",invalid="EXISTS(SELECT 1"+sku+" AND (s.quantity IS NULL OR s.quantity<0))";from+=" AND "+switch(stock){case "IN_STOCK"->available;case "OUT_OF_STOCK"->"("+has+" AND NOT "+available+" AND NOT "+invalid+")";default->"(NOT "+available+" AND (NOT "+has+" OR "+invalid+"))";};}
        long total=db.count("SELECT COUNT(*)"+from,args.toArray());args.add(size);args.add((page-1)*size);var selected=db.rows("SELECT CAST(c.goods_id AS CHAR) AS id"+from+" ORDER BY d.updated_at DESC,c.goods_id DESC LIMIT ? OFFSET ?",args.toArray());var records=new ArrayList<JsonElement>();for(var row:selected)records.add(object(goods.detail(id(row,"id"))).get("goods"));return object(ManagerPresentationViews.page(total,page,size,records));
    }
    private void enrich(JsonArray rows){if(rows.isEmpty())return;var categories=lookup.categoryRows();var stores=new HashMap<String,String>();for(var r:db.rows("SELECT CAST(s.id AS CHAR) AS id,s.store_name FROM li_store s JOIN li_p0_store_control c ON c.store_id=s.id"))stores.put(id(r,"id"),id(r,"store_name"));var units=new HashMap<String,String>();for(var r:db.rows("SELECT CAST(id AS CHAR) AS id,name FROM li_goods_unit WHERE delete_flag=0"))units.put(id(r,"id"),id(r,"name"));
        List<Object> ids=new ArrayList<>();for(var item:rows)ids.add(item.getAsJsonObject().get("id").getAsString());String marks=String.join(",",Collections.nCopies(ids.size(),"?"));var submitted=new HashMap<String,Map<String,Object>>();for(var r:db.rows("SELECT CAST(r.goods_id AS CHAR) AS id,r.content_version,r.submitted_at FROM li_p0_goods_review r JOIN li_p0_goods_control c ON c.goods_id=r.goods_id AND c.content_version=r.content_version WHERE r.goods_id IN ("+marks+")",ids.toArray()))submitted.put(id(r,"id"),r);
        for(var item:rows){var row=item.getAsJsonObject();String id=row.get("id").getAsString();row.addProperty("storeName",stores.get(row.get("storeId").getAsString()));row.addProperty("categoryPath",lookup.categoryPath(row.get("categoryId").isJsonNull()?null:row.get("categoryId").getAsString(),categories));row.addProperty("unitName",row.get("unitId").isJsonNull()?null:units.get(row.get("unitId").getAsString()));var submission=submitted.get(id);row.addProperty("submittedAt",submission==null?null:String.valueOf(instant(submission.get("submitted_at"))));}
    }
    public Object goodsDetail(String id){lookup.require("goods.read");identifier(id);var result=object(goods.detail(id));var single=new JsonArray();single.add(result.get("goods"));enrich(single);var reviewers=db.rows("SELECT r.content_version,r.reviewer_id,u.nick_name AS operator_name FROM li_p0_goods_review r LEFT JOIN li_admin_user u ON u.id=r.reviewer_id WHERE r.goods_id=?",id);for(var item:result.getAsJsonArray("reviews")){var review=item.getAsJsonObject();var source=reviewers.stream().filter(r->number(r,"content_version")==review.get("contentVersion").getAsLong()).findFirst().orElse(null);review.addProperty("reviewerName",source==null?null:operator(map("operator_name",source.get("operator_name"),"actor_id",source.get("reviewer_id"))));}result.add("regulationHistory",object(map("rows",db.rows("SELECT a.*,u.nick_name AS operator_name FROM li_p0_audit a LEFT JOIN li_admin_user u ON u.id=a.actor_id AND a.identity_domain='MANAGER' WHERE a.object_id=? AND a.action IN ('goods.force-off','goods.release') ORDER BY a.created_at DESC,a.id DESC",id).stream().map(r->map("action",r.get("action"),"reason",r.get("reason"),"at",instant(r.get("created_at")),"beforeVersion",r.get("before_version"),"afterVersion",r.get("after_version"),"operatorName",operator(r))).toList())).get("rows"));var content=result.getAsJsonObject("payload");if(content.has("brandId")&&!content.get("brandId").isJsonNull()){var brand=db.one("SELECT name FROM li_brand WHERE id=? AND delete_flag=0",content.get("brandId").getAsString());result.addProperty("brandName",brand==null?null:id(brand,"name"));}return result;}
    public Object point(String store,String point){lookup.require("fulfillment.inspect");identifier(store);identifier(point);var nativePoint=fulfillment.pointView(fulfillment.point(point,store),false);return map("point",nativePoint,"history",db.rows("SELECT version,snapshot,created_at FROM li_p0_point_history WHERE point_id=? ORDER BY version DESC",point).stream().map(r->map("version",r.get("version"),"snapshot",object(r.get("snapshot")),"at",instant(r.get("created_at")))).toList());}
}
